namespace rt::cli {

// Bool = false -> Switch; Option[T] = none or a plain default -> Single; Set[T] with a default -> Repeated.
enum class FlagKind : std::uint8_t { Switch, Single, Repeated };

template <class ValueType>
struct Positional {
  std::string_view name;
  ValueType type;
};

template <class ValueType>
struct Flag {
  std::string_view name;
  FlagKind kind;
  ValueType type;  // unused for a Switch
};

template <class ValueType>
struct CommandSpec {
  std::string_view name;
  std::span<const Positional<ValueType>> positionals;
  std::span<const Flag<ValueType>> flags;
};

struct HelpRequest {
  bool to_stdout;  // --help or -h: stdout, exit 0. No arguments: stderr, exit 2.
};

struct UsageError {
  std::string message;  // without "error: " and without the newline
};

// The arguments of one command, each already of its parameter's type.
template <class Value>
struct Bound {
  std::size_t command = 0;
  std::vector<Value> positionals;
  std::vector<std::vector<Value>> flag_values;  // one entry per table flag
  std::vector<bool> flag_seen;
};

template <class Value>
using Parsed = std::variant<Bound<Value>, HelpRequest, UsageError>;

namespace detail {

inline std::string quoted(std::string_view s) {
  std::string out = "\"";
  out += s;
  out += '"';
  return out;
}

inline bool wants_help(std::span<const std::string_view> args) {
  for (const std::string_view a : args) {
    if (a == "--") {
      return false;
    }
    if (a == "--help" || a == "-h") {
      return true;
    }
  }
  return false;
}

}  // namespace detail

// Values names the program's value types: `using Type`, `using Value`,
// `static std::optional<Value> parse(Type, std::string_view)`, `static std::string_view name(Type)`.
// args excludes the program name.
template <class Values>
Parsed<typename Values::Value> parse(std::span<const std::string_view> args,
                                     std::span<const CommandSpec<typename Values::Type>> commands) {
  using Value = typename Values::Value;
  auto usage = [](std::string message) { return Parsed<Value>{UsageError{std::move(message)}}; };
  if (args.empty()) {
    return HelpRequest{.to_stdout = false};
  }
  if (detail::wants_help(args)) {
    return HelpRequest{.to_stdout = true};
  }
  std::size_t index = 0;
  while (index < commands.size() && commands[index].name != args[0]) {
    ++index;
  }
  if (index == commands.size()) {
    return usage("unknown command " + detail::quoted(args[0]));
  }
  const auto& spec = commands[index];
  Bound<Value> bound{.command = index,
                     .positionals = {},
                     .flag_values = std::vector<std::vector<Value>>(spec.flags.size()),
                     .flag_seen = std::vector<bool>(spec.flags.size(), false)};
  bool flags_ended = false;
  for (std::size_t i = 1; i < args.size(); ++i) {
    const std::string_view arg = args[i];
    if (!flags_ended && arg == "--") {
      flags_ended = true;
      continue;
    }
    if (!flags_ended && arg.starts_with("--")) {
      std::size_t at = 0;
      while (at < spec.flags.size() && spec.flags[at].name != arg.substr(2)) {
        ++at;
      }
      if (at == spec.flags.size()) {
        return usage("unknown flag " + std::string(arg));
      }
      const auto& flag = spec.flags[at];
      if (flag.kind == FlagKind::Switch) {
        if (bound.flag_seen[at]) {
          return usage(std::string(arg) + " given twice");
        }
        bound.flag_seen[at] = true;
        continue;
      }
      if (i + 1 == args.size()) {
        return usage(std::string(arg) + " needs a value");
      }
      if (bound.flag_seen[at] && flag.kind != FlagKind::Repeated) {
        return usage(std::string(arg) + " given twice");
      }
      std::optional<Value> value = Values::parse(flag.type, args[++i]);
      if (!value) {
        return usage(std::string(arg) + ": not a " + std::string(Values::name(flag.type)));
      }
      bound.flag_seen[at] = true;
      bound.flag_values[at].push_back(std::move(*value));
      continue;
    }
    const std::size_t at = bound.positionals.size();
    if (at == spec.positionals.size()) {
      return usage("unexpected argument " + detail::quoted(arg));
    }
    const auto& p = spec.positionals[at];
    std::optional<Value> value = Values::parse(p.type, arg);
    if (!value) {
      return usage("<" + std::string(p.name) + ">: not a " + std::string(Values::name(p.type)));
    }
    bound.positionals.push_back(std::move(*value));
  }
  if (bound.positionals.size() < spec.positionals.size()) {
    return usage("missing <" + std::string(spec.positionals[bound.positionals.size()].name) + ">");
  }
  return bound;
}

// Binding parsed values to an event's fields.

// One value of type T as any of the program's values.
template <class Value, class T>
std::optional<Value> as_value(std::optional<T> v) {
  if (!v) {
    return std::nullopt;
  }
  return Value{std::move(*v)};
}

// Option[T] = none: the value given, if any.
template <class T, class Value>
std::optional<T> first(std::vector<Value>& given) {
  if (given.empty()) {
    return std::nullopt;
  }
  return std::get<T>(std::move(given.front()));
}

// A plain default: the value given, else the default.
template <class T, class Value>
T first_or(std::vector<Value>& given, T otherwise) {
  if (given.empty()) {
    return otherwise;
  }
  return std::get<T>(std::move(given.front()));
}

// Set[T]: every value given; repeats collapse.
template <class T, class Value>
std::set<T> all(std::vector<Value>& given) {
  std::set<T> out;
  for (Value& v : given) {
    out.insert(std::get<T>(std::move(v)));
  }
  return out;
}

}  // namespace rt::cli
